// ========== 1. PM2 配置 (ecosystem.config.js) ==========
module.exports = {
  apps: [{
    name: 'api-server',
    script: './dist/server.js',
    instances: 'max',        // 所有 CPU 核心
    exec_mode: 'cluster',    // cluster 模式
    max_memory_restart: '1G', // RSS 超 1G 自动重启该 worker
    env: { NODE_ENV: 'development' },
    env_production: { NODE_ENV: 'production' },
    log_date_format: 'YYYY-MM-DD HH:mm:ss',
    error_file: './logs/error.log',
    out_file: './logs/out.log',
    merge_logs: true          // 多 worker 日志合并
  }]
};
// 启动: pm2 start ecosystem.config.js --env production
// 监控: pm2 monit
// 优雅重载: pm2 reload api-server
// 生成 heapdump: kill -USR2 <pid>（需 pm2-configured）

// ========== 2. 内存监控与泄漏示例 ==========
const http = require('http');

// 定时采样内存
setInterval(() => {
  const { rss, heapUsed, heapTotal, external } = process.memoryUsage();
  console.log(JSON.stringify({
    rss: `${Math.round(rss / 1024 / 1024)}MB`,
    heapUsed: `${Math.round(heapUsed / 1024 / 1024)}MB`,
    heapTotal: `${Math.round(heapTotal / 1024 / 1024)}MB`,
    external: `${Math.round(external / 1024 / 1024)}MB`
  }));
}, 30_000);

// 常见内存泄漏 1: 全局 Map 持续增长
const userSessionCache = new Map();
function handleSession(userId, data) {
  userSessionCache.set(userId, data); // 从不清理 → 持续增长
  // 修复: userSessionCache.set(userId, { data, expireAt: Date.now() + 3600_000 });
  // 定时清理过期条目
}

// 常见内存泄漏 2: EventEmitter listener 累积
const emitter = new (require('events').EventEmitter)();
emitter.setMaxListeners(100); // 提高告警阈值但不解决根因
function onEachRequest() {
  emitter.on('request', () => {}); // 每次请求注册新 listener
  // 修复: 用 once() 或在请求结束时 removeListener
}

// ========== 3. 优雅退出 ==========
const server = http.createServer((req, res) => {
  res.end('ok');
});

let shuttingDown = false;
async function gracefulShutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`Received ${signal}, starting graceful shutdown...`);

  // 1. 停止接收新连接
  server.close(() => console.log('HTTP server closed'));

  // 2. 设置强制退出超时
  const forceExitTimer = setTimeout(() => {
    console.error('Forced exit after timeout');
    process.exit(1);
  }, 10_000);
  forceExitTimer.unref(); // 不阻止进程退出

  // 3. 释放外部资源
  try {
    // await dbPool.end();      // 关闭数据库连接池
    // await redisClient.quit(); // 关闭 Redis
    // await mqConnection.close(); // 关闭消息队列
    console.log('Resources released');
  } catch (err) {
    console.error('Error during cleanup:', err);
  }

  process.exit(0);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

server.listen(3000);

